WALL_FAMILIES = [
 dict(board='29-enceinte-haute-bois',title='Enceinte haute de village — bois',id='high_village_timber',start=49,height=40,walk=32,thickness=8,
      material='Rondins bruns massifs et renforts bois, couronnement simple, petites embases pierre. Hauteur totale40px, marche de ronde32px. Compatible village tempéré, vallée d’Igea ou habitat forestier selon ressources ; pas de neige automatique.'),
 dict(board='30-enceinte-haute-pierre',title='Enceinte haute de bourg — pierre',id='high_village_stone',start=57,height=48,walk=38,thickness=12,
      material='Pierre grise chaude maçonnée, mortier discret, créneaux sobres. Hauteur totale48px, marche de ronde38px. Palette ocre de Sarak possible sans changer la géométrie.'),
 dict(board='31-courtine-haute-chateau',title='Courtine haute de château',id='high_castle_stone',start=65,height=64,walk=52,thickness=16,
      material='Gros blocs de pierre grise, base renforcée sobre, parapet crénelé massif. Hauteur totale64px, marche de ronde52px ; environ3,4fois un humain natif19px. Pas de mur démesuré ou de décor de guerre.'),
]

def expansion(group):
    boards=[]
    for key,title,family,items,materials in HOUSING:
        b=group(key,title,'building',items,materials)
        b.update(category='housing_variants',regionalFamily=family)
        for x in b['items']:
            x.update(function='human_housing',regionalFamily=family)
        boards.append(b)
    for f in WALL_FAMILIES:
        h,w,t=f['height'],f['walk'],f['thickness']
        specs=[
          ('Mur haut droit',f'Vrai mur de protection haut {h}px natifs, fondation et élévation massives E–O ; version N–S = TOUT le couronnement longitudinal vu par-dessus, PAS un pilier dressé. Raccords de même hauteur.',[48,t,h]),
          ('Terminaison haute','Fin propre d’une enceinte haute avec extrémité fermée, même épaisseur et hauteur que le mur droit. La version N–S court sur toute sa longueur dans la carte.',[32,t,h]),
          ('Angle extérieur haut','Vrai L dans les axes de la carte : sommet continu et deux branches longues ; extérieur visible, pas une façade plate avec un poteau.',[48,48,h]),
          ('Angle intérieur haut','Vrai L inversé, montrant le côté intérieur et les consoles de support ; sommet sans fente, emprise orthogonale.',[48,48,h]),
          ('Jonction haute en T','Trois branches réelles dans la carte, couronnement continu, même hauteur de murs et épaisseur, pas une élévation plate.',[48,48,h]),
          ('Platelage de ronde haut',f'Plateforme porteuse vide VUE DU DESSUS dans les deux axes, hauteur de marche {w}px. Pas de barrière intégrée : parapet séparé. Les supports courts suggèrent l’altitude sans masquer la surface praticable.',[48,24,w]),
          ('Escalier frontal de ronde',f'UNIQUE VUE DE FACE : volée de marches horizontales qui monte vers le haut de l’écran jusqu’au palier de ronde à {w}px. AUCUN profil latéral. Deuxième case = même escalier frontal raccordé à un palier vide vu du dessus.',[24,64,w]),
          ('Parapet haut raccordable','Garde-corps plein de protection, créneaux si pierre, à poser EXACTEMENT au bord du platelage. Version N–S = dessus du parapet sur toute sa longueur, raccords haut/bas. Pas de barrière intégrée au plancher.',[48,t,h-w]),
        ]
        items=[(f'M{f["start"]+n:02}',label,brief,envelope) for n,(label,brief,envelope) in enumerate(specs)]
        b=group(f['board'],f['title'],'module',items,f['material'])
        b.update(category='high_fortifications',wallFamily=f['id'],heightPx=h,walkHeightPx=w,thicknessPx=t,layout='high_wall_portrait')
        for n,item in enumerate(b['items']):
            item.update(wallFamily=f['id'],wallHeightPx=h,walkHeightPx=w,
                        orientations=['front'] if n==6 else ['east_west','north_south'],
                        scaleStatus='native_targets_not_measured_png',connectorGridPx=16)
        b['additionalBrief']=f'''Ces murs doivent être visiblement HAUTS : humain19px, mur{h}px de haut ; dessiner à une échelle uniforme, pas un muret arrivant aux épaules. En E–O on voit la grande élévation du mur sous la petite bande de couronnement ; en N–S on voit la bande LONGUE de couronnement dans le plan de carte, avec dalles/sommets successifs et courte face proche en bas. L’altitude physique est la même : on ne réduit pas le mur N–S en clôture basse. Le platelage de ronde est à hauteur{w}px et le parapet séparé s’accole à son bord. Escalier M{f['start']+6} : FACE UNIQUEMENT et RACCORDEMENT PALIER, pas une version de côté. Ajouter un petit exemple d’enceinte en L, haut mur, platelage vu du dessus et escalier FRONTAL. Aucun sol, eau, bâtiment ou paysage. Échelle humain19px séparée en haut. Même caméra que le guide des modules.'''
        boards.append(b)
    b=group('32-portes-hautes-tours','Enceintes hautes — portes et tours','building',[
      ('F09','Porte haute de village en bois','Portail charpenté de40px de hauteur de mur adjacent, galerie de ronde à32px, petite toiture, passage24px de hauteur utile entièrement ouvert. Deux petites ailes de raccord. Quatre vues cardinales réellement distinctes, escalier d’accès intérieur et non latéral visible.',[112,48,80]),
      ('F10','Porte haute de bourg en pierre','Porte fortifiée pour mur48px, ronde38px, maçonnerie grise, passage ouvert24px hauteur et32px largeur, loge haute sans blason. Quatre vues, mur plein sur profils ; pas un passage sur chaque face.',[128,64,96]),
      ('F11','Châtelet de courtine haute','Porte de château à deux tours carrées sobres, raccord mur64px/ronde52px, passage ouvert32px hauteur, deux ailes de rempart très courtes, aucun pont-levis ou fossé. Vue arrière montre la galerie, profils montrent profondeur et raccords, pas une copie de façade.',[144,80,128]),
      ('F12','Tour carrée de flanquement haute','Tour maçonnée carrée simple pour courtine64px, porte de service au niveau du sol, raccords de ronde à52px sur côtés, plate-forme haute et créneaux. Pas de grande flèche de château féérique ; dessiner les mêmes ouvertures et raccords dans les4vues.',[80,80,128]),
    ],'Matériaux du kit bois haut ou pierre haute. Ouvertures à l’échelle humain19px. Pas de drapeaux, armoiries, soldats, terrain ou armes. Entrées et parapets détachables ultérieurement.')
    b.update(category='high_fortifications')
    for x,family in zip(b['items'],['high_village_timber','high_village_stone','high_castle_stone','high_castle_stone']):x['wallFamily']=family
    boards.append(b)
    base=boards[2]
    b=group('33-habitat-igea-hiver','Igea — variantes d’habitation sous neige','seasonal',[
      (x['id']+'-hiver',x['label']+' — hiver',x['brief'].replace('État sans neige.','').replace('Sans neige.','')+' Conserver EXACTEMENT la silhouette, les portes et la géométrie de la maison sans neige ; ajouter seulement la neige sur toits exposés et rebords inutilisés. Accès et marches dégagés, aucun sol enneigé.',x['nativeEnvelope']) for x in base['items']
    ],'Même pierre, rondins et bardeaux que les quatre variantes d’Igea. Neige saisonnière bleu très pâle sur couvertures, aucun autre changement de bâtiment.')
    b.update(category='housing_variants',regionalFamily='Igea',seasonalBaseBoard='25-habitat-igea')
    boards.append(b)
    return boards
